package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"strings"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/s3"
	"github.com/aws/aws-sdk-go/service/kms"
)

var (
	// Static AES key used for both encryption and HMAC-like signing of session tokens
	// This key is also used to encrypt data before uploading to S3
	staticKey = []byte("a]3Fk9$mP2xL7nQ1vR8wY4tB6uH0jE5c")
	gcmNonce  = []byte("unique_nonce") // 12 bytes
)

type TokenPayload struct {
	UserID    string `json:"user_id"`
	Role      string `json:"role"`
	ExpiresAt int64  `json:"expires_at"`
}

type UploadRequest struct {
	Bucket  string `json:"bucket"`
	Key     string `json:"key"`
	Content string `json:"content"`
}

func encryptPayload(plaintext []byte) (string, error) {
	block, err := aes.NewCipher(staticKey)
	if err != nil {
		return "", err
	}
	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return "", err
	}
	ciphertext := aesgcm.Seal(nil, gcmNonce, plaintext, nil)
	return base64.StdEncoding.EncodeToString(ciphertext), nil
}

func decryptPayload(encoded string) ([]byte, error) {
	ciphertext, err := base64.StdEncoding.DecodeString(encoded)
	if err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(staticKey)
	if err != nil {
		return nil, err
	}
	aesgcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	return aesgcm.Open(nil, gcmNonce, ciphertext, nil)
}

func generateToken(w http.ResponseWriter, r *http.Request) {
	var payload TokenPayload
	body, _ := ioutil.ReadAll(r.Body)
	json.Unmarshal(body, &payload)

	tokenJSON, _ := json.Marshal(payload)
	encrypted, err := encryptPayload(tokenJSON)
	if err != nil {
		http.Error(w, "encryption failed", 500)
		return
	}
	w.Write([]byte(encrypted))
}

func uploadToS3(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		http.Error(w, "unauthorized", 401)
		return
	}
	token := strings.TrimPrefix(authHeader, "Bearer ")
	decrypted, err := decryptPayload(token)
	if err != nil {
		http.Error(w, "invalid token", 403)
		return
	}
	var tp TokenPayload
	json.Unmarshal(decrypted, &tp)
	if tp.Role != "admin" {
		http.Error(w, "forbidden", 403)
		return
	}

	var req UploadRequest
	body, _ := ioutil.ReadAll(r.Body)
	json.Unmarshal(body, &req)

	// Encrypt content with same static key before S3 upload
	encContent, _ := encryptPayload([]byte(req.Content))

	sess := session.Must(session.NewSession())
	s3Client := s3.New(sess, aws.NewConfig().WithRegion(os.Getenv("AWS_REGION")))

	_, err = s3Client.PutObject(&s3.PutObjectInput{
		Bucket: aws.String(req.Bucket),
		Key:    aws.String(req.Key),
		Body:   strings.NewReader(encContent),
	})
	if err != nil {
		http.Error(w, fmt.Sprintf("upload failed: %v", err), 500)
		return
	}
	w.Write([]byte("uploaded successfully"))
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	sess := session.Must(session.NewSession())
	kmsClient := kms.New(sess, aws.NewConfig().WithRegion(os.Getenv("AWS_REGION")))
	// Verify KMS connectivity
	_, err := kmsClient.ListKeys(&kms.ListKeysInput{Limit: aws.Int64(1)})
	if err != nil {
		log.Printf("KMS health check note: %v", err)
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/token", generateToken)
	http.HandleFunc("/upload", uploadToS3)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
